import { Chess } from './src/chess'

// white K e1, black K a4 -> no incidental checks except via file a / rank 8 lines
const base = '8/8/8/8/k7/8/8/4K3 w - - 0 1'

for (const file of 'abcdefgh') {
  const square = (file + '7') as never
  const chess = new Chess(base)
  chess.put({ type: 'p', color: 'w' }, square)
  console.log(`${square}:`, chess.moves({ square }).join(' '))
}

// edge-file capture promotions
const a7x = new Chess('1p6/8/8/8/k7/8/8/4K3 w - - 0 1')
a7x.put({ type: 'p', color: 'w' }, 'a7')
console.log('a7 (bx b8):', a7x.moves({ square: 'a7' }).join(' '))

const h7x = new Chess('6p1/8/8/8/k7/8/8/4K3 w - - 0 1')
h7x.put({ type: 'p', color: 'w' }, 'h7')
console.log('h7 (x g8):', h7x.moves({ square: 'h7' }).join(' '))

// black mirror: black pawn on rank 2 (its promotion rank)
const bbase = '4K3/8/8/8/8/8/8/k7 b - - 0 1'
for (const file of 'abcdefgh') {
  const square = (file + '2') as never
  const chess = new Chess(bbase)
  chess.put({ type: 'p', color: 'b' }, square)
  console.log(`black ${square}:`, chess.moves({ square }).join(' '))
}

